 foreach($scbSlots as $slot)if(($booked_slots[$date][$slot['value']]??0)<CounselingAppointment::MAX_PER_TIME)$free++;
 $reason=$date<$scbToday?'Past date':($date===$scbToday?'Booking starts tomorrow':($closed?(isset($school_closure_dates[$date])?$school_closure_dates[$date]['reason']:($holiday?'Holiday':'Sunday — office closed')):($capacity['is_reached']?'Daily limit reached':($free?'Available':'All time slots are full'))));
