 $scbDays[$date]=['date'=>$date,'day'=>$d,'available'=>$available,'closed'=>$closed,'holiday'=>$holiday,'closure'=>isset($school_closure_dates[$date]),'reason'=>$reason,'free'=>$free,'capacity'=>$capacity,'events'=>$events,'mine'=>$my_appointments[$date]??[]];
}
